import{_ as t,a,c as r,ac as s}from"./chunks/framework.BSuaGltH.js";const S=JSON.parse('{"title":"Nuxt SSR：首屏、注水与请求作用域","description":"用Nuxt4本地课程目录理解SSR与SPA、hydration和请求隔离；示例未执行，仅静态检查。","frontmatter":{"title":"Nuxt SSR：首屏、注水与请求作用域","description":"用Nuxt4本地课程目录理解SSR与SPA、hydration和请求隔离；示例未执行，仅静态检查。","showdocs":{"topics":[{"id":"vue","title":"Vue","link":"/topics/vue/"}],"kind":"响应式与组件","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Nuxt SSR：请求作用域与本地课程目录","summary":"用Nuxt4本地课程目录理解SSR与SPA、hydration和请求隔离；示例未执行，仅静态检查。","status":"active","related":[{"title":"Nuxt SSR排障：不匹配、404、缓存与部署","link":"/programming/web-plus/vue/plus/troubleshooting/ssr-diagnostics","kind":"排错","scope":"general","audience":"general"},{"title":"Nuxt SSR实践：本地课程目录完整项目","link":"/programming/web-plus/vue/plus/practice/ssr-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"Nuxt SSR实践：本地课程目录完整项目 · Nuxt课程目录的手写契约约定了什么至Nuxt本地API怎样限制输入和响应数据","link":"/programming/web-plus/vue/plus/practice/ssr-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"Nuxt SSR实践：本地课程目录完整项目 · Nuxt课程目录后续怎样安装和验收至练习：扩展公开课程","link":"/programming/web-plus/vue/plus/practice/ssr-application-part-02","kind":"开发实践","scope":"general","audience":"general"},{"title":"Vue Router排障：刷新、404、竞态与提交","link":"/programming/web-plus/vue/plus/troubleshooting/router-diagnostics","kind":"排错","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Nuxt SSR数据：稳定键、序列化与保密边界","link":"/programming/web-plus/vue/plus/subjects/ssr-data"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Nuxt SSR数据：稳定键、序列化与保密边界","link":"/programming/web-plus/vue/plus/subjects/ssr-data"}},"headers":[],"relativePath":"programming/web-plus/vue/plus/subjects/ssr-model.md","filePath":"programming/web-plus/vue/plus/subjects/ssr-model.md"}'),o={name:"programming/web-plus/vue/plus/subjects/ssr-model.md"};function n(u,e,i,l,p,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="nuxt-ssr-首屏、注水与请求作用域" tabindex="-1">Nuxt SSR：首屏、注水与请求作用域 <a class="header-anchor" href="#nuxt-ssr-首屏、注水与请求作用域" aria-label="Permalink to &quot;Nuxt SSR：首屏、注水与请求作用域&quot;">​</a></h1><p>本系列承接Vue响应式和Vue Router导航，采用Nuxt4课程目录，研究同一页面在服务器与浏览器中的两次工作。示例未执行；所有运行步骤与现象都是未来验收预期，不是构建或浏览器记录。先读本篇与<a href="/programming/web-plus/vue/plus/subjects/ssr-data">数据边界</a>，再读<a href="/programming/web-plus/vue/plus/practice/ssr-application">完整源码</a>与<a href="/programming/web-plus/vue/plus/troubleshooting/ssr-diagnostics">排障</a>。</p><h2 id="ssr-spa" tabindex="-1">Nuxt的SSR和SPA首屏有什么区别 <a class="header-anchor" href="#ssr-spa" aria-label="Permalink to &quot;Nuxt的SSR和SPA首屏有什么区别 {#ssr-spa}&quot;">​</a></h2><p>Nuxt的SSR和SPA首屏有什么区别？SSR在服务器生成含课程内容的HTML，SPA通常先交付页面外壳，再由浏览器执行脚本读取课程。两者都可以在后续使用客户端导航；SSR不等于每次点击都重新下载整页，也不等于浏览器不需要JavaScript。目录首页与详情首屏需要公开内容，本例保留默认SSR；内网交互面板若只关心登录后操作，则需衡量服务器成本再选模式。</p><p>对这个三条课程目录，判断SSR的证据应是原始HTML出现课程标题，而非浏览器最终DOM出现标题。静态生成可把相同公开内容提前输出，但本例欢迎语依赖请求语言，整页不能未经分离就预渲染成一份。内容可见性、可交互时间、服务器响应时间是不同指标，不能把SSR写成自动更快或自动解决SEO。原理依据见<a href="https://vuejs.org/guide/scaling-up/ssr.html" target="_blank" rel="noopener noreferrer">Vue SSR指南</a>。</p><h2 id="hydration" tabindex="-1">Nuxt的hydration为什么需要相同初始数据 <a class="header-anchor" href="#hydration" aria-label="Permalink to &quot;Nuxt的hydration为什么需要相同初始数据 {#hydration}&quot;">​</a></h2><p>Nuxt的hydration为什么需要相同初始数据？hydration让浏览器接管服务器已经输出的HTML并绑定事件；初始数据必须描述同一棵组件树。服务器生成false的紧凑偏好，浏览器第一次渲染也从payload恢复false；用户勾选后才更新。若浏览器先读localStorage=true，首轮树就不同，造成不匹配，而不是一次正常的用户操作。</p><p>目录不在模板调用Date.now或Math.random，不做服务器和浏览器各自的时区格式化，也不把服务器取不到的window宽度当首屏条件。应优先用可复现输入；确实依赖浏览器环境的增强，可挂载后更新或隔离为ClientOnly，并提供有意义的回退。隐藏告警或全站关闭SSR会遮住原因，不能替代检查HTML结构和数据来源。</p><h2 id="request-scope" tabindex="-1">Nuxt的useState怎样避免跨请求状态污染 <a class="header-anchor" href="#request-scope" aria-label="Permalink to &quot;Nuxt的useState怎样避免跨请求状态污染 {#request-scope}&quot;">​</a></h2><p>Nuxt的useState怎样避免跨请求状态污染？useState在setup调用时由Nuxt请求上下文管理，以稳定键恢复序列化状态；模块顶层可变ref却可能随服务器进程被多个请求共享。useReadingPreference返回useState(&#39;catalog:compact:v1&#39;,()=&gt;false)，没有把返回值存进模块变量，因而每个SSR请求从独立布尔值开始。客户端同一应用导航仍共享这个偏好，硬刷新又是新请求。</p><p>server/data只共享冻结的公开课程，所有欢迎语在handler内部读取event生成。不能把“上次语言”“当前用户”赋给模块顶层对象，也不能把useState理解成持久数据库。键负责标识同一状态，不能把不同用途误用同一键；敏感信息即便隔离正确，也不应进入可序列化页面状态。依据见<a href="https://nuxt.com/docs/4.x/getting-started/state-management" target="_blank" rel="noopener noreferrer">Nuxt状态管理</a>和<a href="https://nuxt.com/docs/4.x/api/composables/use-state" target="_blank" rel="noopener noreferrer">useState</a>。</p><h2 id="versions" tabindex="-1">Nuxt教学项目为什么固定4.2.2和Node22.14.0 <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Nuxt教学项目为什么固定4.2.2和Node22.14.0 {#versions}&quot;">​</a></h2><p>Nuxt教学项目为什么固定4.2.2和Node22.14.0？4.2.2是已发布版本，其官方manifest要求Node ^20.19.0或&gt;=22.12.0，Node22.14.0属于兼容范围；精确固定直接依赖让读者明确学习对象。项目同时固定Vue3.5.25与Router4.6.3，与该Nuxt标签所列范围一致。此选择不宣称版本最新、无安全问题，也没有验证本机安装结果。</p><p>本例使用Nuxt4的app目录结构，server与fixtures在项目根。没有lock意味着传递依赖仍可能变化，compatibilityDate也不能替代lock或保证所有平台产物一致。官方证据：<a href="https://github.com/nuxt/nuxt/releases/tag/v4.2.2" target="_blank" rel="noopener noreferrer">Nuxt发布</a>、<a href="https://github.com/nuxt/nuxt/blob/v4.2.2/packages/nuxt/package.json" target="_blank" rel="noopener noreferrer">标签manifest</a>、<a href="https://nodejs.org/en/blog/release/v22.14.0" target="_blank" rel="noopener noreferrer">Node发布</a>。</p><h2 id="exercise" tabindex="-1">练习：两次请求与一次点击 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习：两次请求与一次点击 {#exercise}&quot;">​</a></h2><p>A携带en-US请求首页，B携带zh-CN同时请求。A勾选compact后通过NuxtLink进入详情，B随后刷新。画出fixture、welcome、compact各自属于哪个生命周期，并指出把compact提到模块顶层的后果。</p><details class="details custom-block"><summary>参考答案（推演，未执行）</summary><p>公开冻结fixture属于进程可共享输入；welcome属于各自event与响应；compact属于各自SSR上下文并进入各自payload。A客户端导航保留true，B刷新仍从false初始化。模块顶层可变compact可能使A影响B；即使加固定useState键，也不能把结果放入共享模块变量。没有任何用户身份或跨设备同步功能。</p></details>',17)])])}const g=t(o,[["render",n]]);export{S as __pageData,g as default};
